const source="// Internal callback SLA only. No messaging provider is called by this code.\nconst policy={\"version\":\"2026-10-20\",\"approvedByOwnerInChat\":true,\"scope\":\"intake, questionnaire, CRM documentation, response, appointment coordination\",\"owner\":\"yoram\",\"customerContactPhone\":\"excelent_contact\",\"timezone\":\"Asia/Jerusalem\",\"businessHours\":{\"days\":[0,1,2,3,4],\"open\":\"08:30\",\"close\":\"20:00\"},\"responseMinutes\":{\"questionnaireSubmittedWithKnownAnswers\":30,\"withoutQuestionnaire\":60},\"outsideBusinessHours\":\"next_business_day\",\"holidayCalendar\":null,\"activationStatus\":\"callback_delivery_not_verified_in_live_operations_see_release_report_for_deployment\",\"testMessaging\":{\"allowedRecipientPhone\":\"yoram_050\",\"allowedE164\":\"972502234052\",\"purpose\":\"internal acceptance tests only\",\"realCustomersAllowed\":false,\"groupsAllowed\":false},\"deferred\":[\"SMS\",\"email nurturing\",\"WhatsApp tips group\"],\"notes\":[\"Questionnaire answers may include unknown or skipped details; do not demand financial documents before returning to the lead.\",\"This file records owner decisions. See the release report for the deployed reminder version; a callback or appointment still requires operational evidence.\",\"Business hours count in Israel time; advertising account schedules currently display PDT.\",\"Do not silently reuse the existing 45-minute reminder as proof of the new 30/60-minute SLA.\"]};\n// Column ids, sources and open stages come from the campaign's intake block ({\"campaign\":\"refi\",\"board\":\"5106246268\",\"group\":\"topics\",\"newStage\":\"ליד חדש\",\"reminder\":{\"sourcePattern\":\"LP1|מטא|וואטסאפ\",\"openStages\":[\"ליד חדש\",\"התקבל\",\"\"]},\"columns\":{\"balance\":\"refi_balance\",\"goal\":\"refi_goal\",\"goal2\":\"color_mm88h0j8\",\"otherLoans\":\"refi_other_loans\",\"pay\":\"color_mm88h799\",\"left\":\"color_mm885m0t\",\"when\":\"color_mm88cffb\",\"ask\":\"color_mm88fzyb\",\"doc\":\"color_mm88catt\",\"heatLabel\":\"color_mm88xpa8\",\"heatDetail\":\"long_text_mm88pfdv\",\"answers\":\"long_text_mm88xzfe\",\"complexity\":\"long_text_mm88cs6f\",\"hasMortgage\":\"dropdown_mm88dkb2\",\"serviceRequestAt\":\"date_mm88hmw2\",\"marketingAt\":\"date_mm88qwfm\",\"messageReceived\":\"boolean_mm88aae4\",\"entered\":\"refi_entered\",\"feasibility\":\"color_mm88hss3\",\"phone\":\"refi_phone\",\"stage\":\"refi_stage\",\"source\":\"refi_source\",\"heat\":\"numeric_mm883h9v\",\"firstReply\":\"refi_first_reply\",\"consentMarketing\":\"boolean_mm88mzry\",\"consentService\":\"boolean_mm8848pn\",\"email\":\"fn_email\",\"permissions\":\"long_text_mm8ag9s\"}} via source.js).\nconst K={\"campaign\":\"refi\",\"board\":\"5106246268\",\"group\":\"topics\",\"newStage\":\"ליד חדש\",\"reminder\":{\"sourcePattern\":\"LP1|מטא|וואטסאפ\",\"openStages\":[\"ליד חדש\",\"התקבל\",\"\"]},\"columns\":{\"balance\":\"refi_balance\",\"goal\":\"refi_goal\",\"goal2\":\"color_mm88h0j8\",\"otherLoans\":\"refi_other_loans\",\"pay\":\"color_mm88h799\",\"left\":\"color_mm885m0t\",\"when\":\"color_mm88cffb\",\"ask\":\"color_mm88fzyb\",\"doc\":\"color_mm88catt\",\"heatLabel\":\"color_mm88xpa8\",\"heatDetail\":\"long_text_mm88pfdv\",\"answers\":\"long_text_mm88xzfe\",\"complexity\":\"long_text_mm88cs6f\",\"hasMortgage\":\"dropdown_mm88dkb2\",\"serviceRequestAt\":\"date_mm88hmw2\",\"marketingAt\":\"date_mm88qwfm\",\"messageReceived\":\"boolean_mm88aae4\",\"entered\":\"refi_entered\",\"feasibility\":\"color_mm88hss3\",\"phone\":\"refi_phone\",\"stage\":\"refi_stage\",\"source\":\"refi_source\",\"heat\":\"numeric_mm883h9v\",\"firstReply\":\"refi_first_reply\",\"consentMarketing\":\"boolean_mm88mzry\",\"consentService\":\"boolean_mm8848pn\",\"email\":\"fn_email\",\"permissions\":\"long_text_mm8ag9s\"}},KC=K.columns,R=K.reminder;\nconst quizPattern=new RegExp(\"(?:^|\\\\n)(?:יש לכם היום משכנתא|מה המטרה העיקרית|מה יתרת המשכנתא בקירוב|מה ההחזר החודשי היום|כמה זמן נשאר לתשלום|מתי תרצו לפעול|מה אתם מבקשים כרגע|יש לכם דוח יתרות לסילוק עדכני|יש הלוואות נוספות מלבד המשכנתא|צפוי שינוי בהכנסה בשנים הקרובות|מתוכננים מכירה של הנכס או פירעון גדול|יש קושי בתשלומים היום)\\\\? .+\");\nconst response=$input.first().json;\nconst page=response.data?.boards?.[0]?.groups?.[0]?.items_page;\nif(response.errors?.length||!Array.isArray(page?.items)||page.cursor)throw Error('Incomplete Monday SLA lookup');\nconst sd=$getWorkflowStaticData('global'),now=Date.now();\nconst fmt=new Intl.DateTimeFormat('en-GB',{timeZone:policy.timezone,weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false});\nconst days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];\nconst mins=s=>{const [h,m]=s.split(':').map(Number);return h*60+m;};\nfunction open(t){const p={};fmt.formatToParts(new Date(t)).forEach(x=>p[x.type]=x.value);const m=(+p.hour%24)*60+(+p.minute);return policy.businessHours.days.includes(days.indexOf(p.weekday))&&m>=mins(policy.businessHours.open)&&m<mins(policy.businessHours.close);}\nif(!open(now))return [];\nfunction elapsed(from,to,cap){let total=0;for(let t=from;t<to&&total<cap;){const end=Math.min(to,(Math.floor(t/60000)+1)*60000);if(open(t))total+=end-t;t=end;}return total;}\nconst out=[];\nfor(const it of page.items){\n const cv=Object.fromEntries((it.column_values||[]).map(c=>[c.id,c]));\n const text=id=>cv[id]?.text||'';\n if(!new RegExp(R.sourcePattern,'i').test(text(KC.source)))continue;\n if(!R.openStages.includes(text(KC.stage))||text(KC.firstReply).trim())continue;\n let requested=Date.parse(it.created_at);\n try{const d=JSON.parse(cv[KC.serviceRequestAt]?.value||'null');if(d?.date)requested=Date.parse(d.date+'T'+(d.time||'00:00:00')+'Z');}catch(e){continue;}\n if(!Number.isFinite(requested)||requested>now||now-requested>3*86400000)continue;\n const questionnaire=quizPattern.test(text(KC.answers));\n const limit=questionnaire?policy.responseMinutes.questionnaireSubmittedWithKnownAnswers:policy.responseMinutes.withoutQuestionnaire;\n const key=String(it.id)+':'+requested+':'+limit;\n if(sd.reminded?.[key]||Number(sd.reminded?.[it.id]||0)>=requested)continue;\n if(elapsed(requested,now,limit*60000)<limit*60000)continue;\n out.push({json:{item:String(it.id),reminderKey:key,requestedAt:requested,thresholdMinutes:limit,questionnaire,leadName:it.name,source:text(KC.source),phone:text(KC.phone),text:`תזכורת ליורם פלד: פנייה ${it.id} טרם טופלה לאחר ${limit} דקות פעילות (${questionnaire?'נשלחו תשובות שאלון':'ללא תשובות שאלון'}). שעות הפעילות א׳–ה׳ 08:30–20:00.`}});\n}\n// Cache acknowledgment belongs after confirmed internal notification, never here.\nreturn out;\n",ack="// Per-item acknowledgment of a confirmed Monday internal notification.\nconst planned=$('Pick overdue').item.json;\nif($json.errors?.length||!$json.data?.create_notification?.text)throw Error('Internal notification not confirmed; keep eligible for retry');\nif(!planned.item||!planned.reminderKey)throw Error('Missing reminder ownership');\nconst sd=$getWorkflowStaticData('global');sd.reminded=sd.reminded||{};\nsd.reminded[planned.reminderKey]=Date.now();\nfor(const [k,t]of Object.entries(sd.reminded))if(Date.now()-Number(t)>7*86400000)delete sd.reminded[k];\nreturn {json:{...planned,notificationConfirmed:true}};\n";
